"""Chebyshev correspondence: mode count equals algebraic degree.

Builds the n-th Chebyshev polynomial T_n by recurrence, confirms it has degree
exactly n, and checks numerically that T_n(cos theta) = cos(n theta), the identity
that turns 'number of spatial modes' into 'algebraic degree of the pattern'.
"""
from __future__ import annotations
import math
from typing import List, Tuple


def chebyshev_T(n: int) -> List[float]:
    if n == 0:
        return [1.0]
    if n == 1:
        return [0.0, 1.0]
    prev2, prev1 = [1.0], [0.0, 1.0]
    for _ in range(2, n + 1):
        cur = [0.0] + [2.0 * c for c in prev1]
        for i, c in enumerate(prev2):
            cur[i] -= c
        prev2, prev1 = prev1, cur
    return prev1


def poly_eval(coeffs: List[float], x: float) -> float:
    acc = 0.0
    for c in reversed(coeffs):
        acc = acc * x + c
    return acc


def degree(coeffs: List[float], tol: float = 1e-9) -> int:
    return max(i for i, c in enumerate(coeffs) if abs(c) > tol)


def verify(n: int, samples: int = 400) -> Tuple[int, float]:
    coeffs = chebyshev_T(n)
    err = max(
        abs(poly_eval(coeffs, math.cos(math.pi * k / (samples - 1)))
            - math.cos(n * math.pi * k / (samples - 1)))
        for k in range(samples)
    )
    return degree(coeffs), err


if __name__ == "__main__":
    for n in range(7):
        d, e = verify(n)
        print(f"n={n}: degree(T_n)={d}, leading_coeff={chebyshev_T(n)[-1]:.0f}, "
              f"max_err={e:.1e}")

