function ChebyshevT(n):
    if n == 0: return [1]
    if n == 1: return [0, 1]
    prev2 <- [1]          # T_0
    prev1 <- [0, 1]       # T_1
    for k from 2 to n:
        cur <- shiftUp(scale(prev1, 2))   # 2 * X * T_{k-1}
        cur <- subtract(cur, prev2)        # - T_{k-2}
        prev2, prev1 <- prev1, cur
    return prev1

function DegreeMatchesMode(n):
    coeffs <- ChebyshevT(n)
    assert leadingIndex(coeffs) == n           # degree = mode number
    assert coeffs[n] == 2^(n-1)                # top mode cannot cancel

