function GrayScott(n, steps, Du, Dv, F, k):
    initialize u=1, v=0; seed a central square with u=0.5, v=0.25
    repeat steps times:
        for each cell (i,j):
            uvv <- u*v*v
            u' <- u + Du*Lap(u) - uvv + F*(1-u)
            v' <- v + Dv*Lap(v) + uvv - (F+k)*v
        u,v <- u',v'
    return v

function ExtractLevelSet(field):
    mean <- average(field)
    return { (x,y) : |field(x,y) - mean| < eps }

function Classify(points):
    (A,C) <- leastSquaresFit(A x^2 + C y^2 = 1, points)
    return sign(-4 A C)   # discriminant with B=0

